 "content": "from collections import Counter


def transform(grid):
    """Fill the interiors of monochrome rectangular outlines.

    Frames with odd-by-odd interiors are filled with 7; even-by-even
    interiors are filled with 2.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find complete rectangular perimeters, allowing other same-colored
    # objects elsewhere in the grid to be separate or nearby.
    for color in set(v for row in grid for v in row):
        if color == background:
            continue
        for top in range(h - 2):
            for bottom in range(top + 2, h):
                valid_cols = [c for c in range(w)
                              if grid[top][c] == color and grid[bottom][c] == color]
                for i, left in enumerate(valid_cols):
                    for right in valid_cols[i + 1:]:
                        if right - left < 2:
                            continue
                        if any(grid[r][left] != color or grid[r][right] != color
                               for r in range(top + 1, bottom)):
                            continue
                        if any(grid[top][c] != color or grid[bottom][c] != color
                               for c in range(left + 1, right)):
                            continue
                        interior = [grid[r][c]
                                    for r in range(top + 1, bottom)
                                    for c in range(left + 1, right)]
                        if any(v != background for v in interior):
                            continue
                        ih, iw = bottom - top - 1, right - left - 1
                        fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = fill
    return out
